"""Export canonical Python schemas and enums; generated files are committed artifacts."""
from __future__ import annotations

import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from services.api.app import contracts


def main():
    target = ROOT / "contracts"
    target.mkdir(exist_ok=True)
    models = ["ClaimIR", "IntentIR", "ConfirmedClaimSnapshot", "ExtractionCandidate", "CompactExtractionCandidate", "AlignmentCandidate"]
    for name in models:
        model = getattr(contracts, name)
        (target / f"{name}.schema.json").write_text(json.dumps(model.model_json_schema(), indent=2, ensure_ascii=False)+"\n", encoding="utf-8")
    from services.api.app.review import SourceImport, BriefDraft
    for model in (SourceImport,BriefDraft):
        (target / f"{model.__name__}.schema.json").write_text(json.dumps(model.model_json_schema(),indent=2,ensure_ascii=False)+"\n",encoding="utf-8")
    enum_names = ["CaseState", "Route", "Coverage", "EvidenceStatus", "EffectDirection", "Applicability", "SystemStatus", "OperatorState"]
    lines = ["// Generated by scripts/export_contracts.py. Do not edit by hand."]
    for name in enum_names:
        values = [member.value for member in getattr(contracts,name)]
        lines.append(f"export const {name}Values = {json.dumps(values)} as const;")
        lines.append(f"export type {name} = typeof {name}Values[number];")
    (target / "state-types.ts").write_text("\n".join(lines)+"\n", encoding="utf-8")
    from services.api.app.main import app
    (target / "openapi.json").write_text(json.dumps(app.openapi(), indent=2)+"\n",encoding="utf-8")
    print(f"Exported {len(models)+2} schemas, canonical TypeScript enums and OpenAPI.")


if __name__ == "__main__":
    main()
